(function () {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-vanilla';

  var todoList = document.querySelector('.todo-list');
  var newTodoInput = document.querySelector('.new-todo');
  var toggleAllCheckbox = document.getElementById('toggle-all');
  var todoCount = document.querySelector('.todo-count');
  var clearCompletedBtn = document.querySelector('.clear-completed');
  var mainSection = document.querySelector('.main');
  var footerSection = document.querySelector('.footer');
  var filterLinks = document.querySelectorAll('.filters a');

  // ── Model ──────────────────────────────────────────────

  function loadTodos() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      return [];
    }
  }

  function saveTodos(todos) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
  }

  // ── Rendering ──────────────────────────────────────────

  function getActiveFilter() {
    var hash = window.location.hash || '#/';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  function createTodoElement(todo) {
    var li = document.createElement('li');
    li.dataset.id = todo.id;
    if (todo.completed) li.classList.add('completed');

    var viewDiv = document.createElement('div');
    viewDiv.className = 'view';

    var checkbox = document.createElement('input');
    checkbox.className = 'toggle';
    checkbox.type = 'checkbox';
    checkbox.checked = todo.completed;

    var label = document.createElement('label');
    label.textContent = todo.title;

    var destroyBtn = document.createElement('button');
    destroyBtn.className = 'destroy';

    viewDiv.appendChild(checkbox);
    viewDiv.appendChild(label);
    viewDiv.appendChild(destroyBtn);

    var editInput = document.createElement('input');
    editInput.className = 'edit';
    editInput.value = todo.title;

    li.appendChild(viewDiv);
    li.appendChild(editInput);
    return li;
  }

  function render() {
    var todos = loadTodos();
    var filter = getActiveFilter();

    // Filter todos
    var filtered = todos.filter(function (todo) {
      if (filter === 'active') return !todo.completed;
      if (filter === 'completed') return todo.completed;
      return true;
    });

    // Render list
    todoList.innerHTML = '';
    filtered.forEach(function (todo) {
      todoList.appendChild(createTodoElement(todo));
    });

    // Update count
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + (activeCount === 1 ? 'item' : 'items') + ' left';

    // Show/hide main and footer
    var hasTodos = todos.length > 0;
    mainSection.style.display = hasTodos ? '' : 'none';
    footerSection.style.display = hasTodos ? '' : 'none';

    // Toggle-all state
    var allCompleted = todos.length > 0 && todos.every(function (t) { return t.completed; });
    toggleAllCheckbox.checked = allCompleted;

    // Clear completed visibility
    var hasCompleted = todos.some(function (t) { return t.completed; });
    clearCompletedBtn.style.display = hasCompleted ? '' : 'none';

    // Active filter link
    filterLinks.forEach(function (link) {
      var linkHash = link.getAttribute('href');
      if (filter === 'all' && linkHash === '#/') link.classList.add('selected');
      else if (filter === 'active' && linkHash === '#/active') link.classList.add('selected');
      else if (filter === 'completed' && linkHash === '#/completed') link.classList.add('selected');
      else link.classList.remove('selected');
    });
  }

  // ── Actions ────────────────────────────────────────────

  function addTodo(title) {
    var trimmed = title.trim();
    if (!trimmed) return;
    var todos = loadTodos();
    todos.push({ id: generateId(), title: trimmed, completed: false });
    saveTodos(todos);
    render();
  }

  function toggleTodo(id) {
    var todos = loadTodos();
    todos.forEach(function (todo) {
      if (todo.id === id) todo.completed = !todo.completed;
    });
    saveTodos(todos);
    render();
  }

  function destroyTodo(id) {
    var todos = loadTodos().filter(function (todo) { return todo.id !== id; });
    saveTodos(todos);
    render();
  }

  function editTodo(id, newTitle) {
    var trimmed = newTitle.trim();
    var todos = loadTodos();
    if (!trimmed) {
      todos = todos.filter(function (todo) { return todo.id !== id; });
    } else {
      todos.forEach(function (todo) {
        if (todo.id === id) todo.title = trimmed;
      });
    }
    saveTodos(todos);
    render();
  }

  function toggleAll() {
    var todos = loadTodos();
    var allCompleted = todos.length > 0 && todos.every(function (t) { return t.completed; });
    todos.forEach(function (todo) { todo.completed = !allCompleted; });
    saveTodos(todos);
    render();
  }

  function clearCompleted() {
    var todos = loadTodos().filter(function (todo) { return !todo.completed; });
    saveTodos(todos);
    render();
  }

  // ── Event delegation ───────────────────────────────────

  newTodoInput.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodoInput.value);
      newTodoInput.value = '';
    }
  });

  todoList.addEventListener('click', function (e) {
    var target = e.target;
    var li = target.closest('li');
    if (!li) return;
    var id = li.dataset.id;

    if (target.classList.contains('destroy')) {
      destroyTodo(id);
    } else if (target.classList.contains('toggle')) {
      toggleTodo(id);
    }
  });

  todoList.addEventListener('dblclick', function (e) {
    var target = e.target;
    if (target.tagName !== 'LABEL') return;
    var li = target.closest('li');
    if (!li) return;
    li.classList.add('editing');
    var editInput = li.querySelector('.edit');
    editInput.value = target.textContent;
    editInput.focus();
  });

  todoList.addEventListener('focusout', function (e) {
    var target = e.target;
    if (!target.classList.contains('edit')) return;
    var li = target.closest('li');
    if (!li) return;
    if (!li.classList.contains('editing')) return;
    li.classList.remove('editing');
    editTodo(li.dataset.id, target.value);
  });

  todoList.addEventListener('keydown', function (e) {
    var target = e.target;
    if (!target.classList.contains('edit')) return;
    var li = target.closest('li');
    if (!li) return;
    if (e.keyCode === ENTER_KEY) {
      li.classList.remove('editing');
      editTodo(li.dataset.id, target.value);
    } else if (e.keyCode === ESCAPE_KEY) {
      li.classList.remove('editing');
      target.value = li.querySelector('label').textContent;
    }
  });

  toggleAllCheckbox.addEventListener('change', toggleAll);
  clearCompletedBtn.addEventListener('click', clearCompleted);

  // ── Routing ────────────────────────────────────────────

  window.addEventListener('hashchange', render);

  // ── Init ───────────────────────────────────────────────

  render();
})();

const { Given, When, Then } = require('@cucumber/cucumber');

// ── Given ────────────────────────────────────────────────

Given('the app is loaded', function () {
  // app is already loaded by world.js Before hook
});

Given('the app is loaded with no todos', function () {
  this.localStorage.clear();
});

Given('the user has added a todo {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new KeyboardEvent('keydown', { keyCode: 13, key: 'Enter', bubbles: true }));
});

Given('the user has added todos {string} and {string}', function (a, b) {
  const input = this.document.querySelector('.new-todo');
  input.value = a;
  input.dispatchEvent(new KeyboardEvent('keydown', { keyCode: 13, key: 'Enter', bubbles: true }));
  input.value = b;
  input.dispatchEvent(new KeyboardEvent('keydown', { keyCode: 13, key: 'Enter', bubbles: true }));
});

Given('all todos are completed', function () {
  const toggleAll = this.document.getElementById('toggle-all');
  toggleAll.checked = true;
  toggleAll.dispatchEvent(new Event('change', { bubbles: true }));
});

Given('the todo {string} is completed', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      const checkbox = li.querySelector('.toggle');
      if (!checkbox.checked) {
        checkbox.checked = true;
        checkbox.dispatchEvent(new Event('change', { bubbles: true }));
      }
      return;
    }
  }
  throw new Error(`Todo "${title}" not found`);
});

Given('the todo {string} is in editing mode', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      if (!li.classList.contains('editing')) {
        label.dispatchEvent(new Event('dblclick', { bubbles: true }));
      }
      return;
    }
  }
  throw new Error(`Todo "${title}" not found`);
});

// ── When ─────────────────────────────────────────────────

When('the user types {string} in the new todo input and presses Enter', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new KeyboardEvent('keydown', { keyCode: 13, key: 'Enter', bubbles: true }));
});

When('the user checks the toggle-all checkbox', function () {
  const toggleAll = this.document.getElementById('toggle-all');
  toggleAll.checked = true;
  toggleAll.dispatchEvent(new Event('change', { bubbles: true }));
});

When('the user unchecks the toggle-all checkbox', function () {
  const toggleAll = this.document.getElementById('toggle-all');
  toggleAll.checked = false;
  toggleAll.dispatchEvent(new Event('change', { bubbles: true }));
});

When('the user checks the todo {string} checkbox', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      const checkbox = li.querySelector('.toggle');
      checkbox.checked = true;
      checkbox.dispatchEvent(new Event('change', { bubbles: true }));
      return;
    }
  }
  throw new Error(`Todo "${title}" not found`);
});

When('the user unchecks the todo {string} checkbox', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      const checkbox = li.querySelector('.toggle');
      checkbox.checked = false;
      checkbox.dispatchEvent(new Event('change', { bubbles: true }));
      return;
    }
  }
  throw new Error(`Todo "${title}" not found`);
});

When('the user destroys the todo {string}', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      const destroyBtn = li.querySelector('.destroy');
      destroyBtn.click();
      return;
    }
  }
  throw new Error(`Todo "${title}" not found`);
});

When('the user double-clicks the todo {string} label', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      label.dispatchEvent(new MouseEvent('dblclick', { bubbles: true }));
      return;
    }
  }
  throw new Error(`Todo "${title}" not found`);
});

When('the user types {string} in the edit input and presses Enter', function (text) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No editing input found');
  editInput.value = text;
  editInput.dispatchEvent(new KeyboardEvent('keydown', { keyCode: 13, key: 'Enter', bubbles: true }));
});

When('the user types {string} in the edit input and blurs', function (text) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No editing input found');
  editInput.value = text;
  editInput.dispatchEvent(new Event('focusout', { bubbles: true }));
});

When('the user types {string} in the edit input and presses Escape', function (text) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No editing input found');
  editInput.value = text;
  editInput.dispatchEvent(new KeyboardEvent('keydown', { keyCode: 27, key: 'Escape', bubbles: true }));
});

When('the user clears the edit input and presses Enter', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No editing input found');
  editInput.value = '';
  editInput.dispatchEvent(new KeyboardEvent('keydown', { keyCode: 13, key: 'Enter', bubbles: true }));
});

When('the user clicks the clear completed button', function () {
  this.document.querySelector('.clear-completed').click();
});

When('the user navigates to {string}', function (hash) {
  this.navigate(hash);
});

When('the app is reloaded', function () {
  // Save current localStorage data, reload app
  const stored = this.localStorage.getItem('todos-vanilla');
  this.loadApp();
  this.localStorage.setItem('todos-vanilla', stored);
});

When('the user unchecks the first todo', function () {
  const firstToggle = this.document.querySelector('.todo-list li .toggle');
  if (!firstToggle) throw new Error('No todo found');
  firstToggle.checked = false;
  firstToggle.dispatchEvent(new Event('change', { bubbles: true }));
});

// ── Then ─────────────────────────────────────────────────

Then('the todo list contains {int} item(s)', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  if (items.length !== count) {
    throw new Error(`Expected ${count} items but found ${items.length}`);
  }
});

Then('the first todo displays {string}', function (title) {
  const firstLabel = this.document.querySelector('.todo-list li label');
  if (!firstLabel) throw new Error('No todo label found');
  if (firstLabel.textContent !== title) {
    throw new Error(`Expected first todo "${title}" but found "${firstLabel.textContent}"`);
  }
});

Then('the new todo input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  if (input.value !== '') {
    throw new Error(`Expected empty input but found "${input.value}"`);
  }
});

Then('both todos are marked completed', function () {
  const toggles = this.document.querySelectorAll('.todo-list li .toggle');
  if (toggles.length !== 2) throw new Error(`Expected 2 toggles but found ${toggles.length}`);
  if (!toggles[0].checked || !toggles[1].checked) {
    throw new Error('Not all todos are completed');
  }
});

Then('the toggle-all checkbox is checked', function () {
  const toggleAll = this.document.getElementById('toggle-all');
  if (!toggleAll.checked) throw new Error('Toggle-all is not checked');
});

Then('the toggle-all checkbox is unchecked', function () {
  const toggleAll = this.document.getElementById('toggle-all');
  if (toggleAll.checked) throw new Error('Toggle-all is checked');
});

Then('both todos are marked active', function () {
  const toggles = this.document.querySelectorAll('.todo-list li .toggle');
  if (toggles.length !== 2) throw new Error(`Expected 2 toggles but found ${toggles.length}`);
  if (toggles[0].checked || toggles[1].checked) {
    throw new Error('Not all todos are active');
  }
});

Then('the todo {string} is marked completed', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      if (!li.classList.contains('completed')) {
        throw new Error(`Todo "${title}" is not completed`);
      }
      const checkbox = li.querySelector('.toggle');
      if (!checkbox.checked) {
        throw new Error(`Todo "${title}" checkbox is not checked`);
      }
      return;
    }
  }
  throw new Error(`Todo "${title}" not found`);
});

Then('the todo {string} is marked active', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      if (li.classList.contains('completed')) {
        throw new Error(`Todo "${title}" is completed`);
      }
      return;
    }
  }
  throw new Error(`Todo "${title}" not found`);
});

Then('the todo {string} is in editing mode', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      if (!li.classList.contains('editing')) {
        throw new Error(`Todo "${title}" is not in editing mode`);
      }
      return;
    }
  }
  throw new Error(`Todo "${title}" not found`);
});

Then('the counter displays {string}', function (text) {
  const countEl = this.document.querySelector('.todo-count');
  const actual = countEl.textContent.trim();
  if (actual !== text) {
    throw new Error(`Expected counter "${text}" but found "${actual}"`);
  }
});

Then('the clear completed button is hidden', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (btn.style.display !== 'none') {
    throw new Error('Clear completed button is not hidden');
  }
});

Then('the clear completed button is visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (btn.style.display === 'none') {
    throw new Error('Clear completed button is hidden');
  }
});

Then('the {string} filter link is selected', function (name) {
  const links = this.document.querySelectorAll('.filters a');
  for (const link of links) {
    if (link.textContent.trim() === name) {
      if (!link.classList.contains('selected')) {
        throw new Error(`Filter link "${name}" is not selected`);
      }
      return;
    }
  }
  throw new Error(`Filter link "${name}" not found`);
});

Then('the main section is hidden', function () {
  const main = this.document.querySelector('.main');
  if (main.style.display !== 'none') {
    throw new Error('Main section is not hidden');
  }
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  if (main.style.display === 'none') {
    throw new Error('Main section is hidden');
  }
});

Then('the footer is hidden', function () {
  const footer = this.document.querySelector('.todoapp .footer');
  if (footer.style.display !== 'none') {
    throw new Error('Footer is not hidden');
  }
});

Then('the footer is visible', function () {
  const footer = this.document.querySelector('.todoapp .footer');
  if (footer.style.display === 'none') {
    throw new Error('Footer is hidden');
  }
});

const { Given, When, Then } = require('@cucumber/cucumber');

// ── Helpers ──────────────────────────────────────────────

function findTodoByTitle(doc, title) {
  const labels = doc.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) return label.closest('li');
  }
  throw new Error(`Todo "${title}" not found`);
}

function pressEnter(win, el) {
  el.dispatchEvent(new win.KeyboardEvent('keydown', { keyCode: 13, key: 'Enter', bubbles: true }));
}

function pressEscape(win, el) {
  el.dispatchEvent(new win.KeyboardEvent('keydown', { keyCode: 27, key: 'Escape', bubbles: true }));
}

// ── Given ────────────────────────────────────────────────

Given('the app is loaded', function () {
  // loaded by world.js Before hook
});

Given('the app is loaded with no todos', function () {
  this.localStorage.clear();
});

Given('the user has added a todo {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  pressEnter(this.window, input);
});

Given('the user has added todos {string} and {string}', function (a, b) {
  const input = this.document.querySelector('.new-todo');
  input.value = a;
  pressEnter(this.window, input);
  input.value = b;
  pressEnter(this.window, input);
